<div class="container py-5"><nav><a href="<?= url('/') ?>">الرئيسية</a> / <a href="<?= url('/categories/'.$product['category_slug']) ?>"><?= e($product['category_name']) ?></a> / <?= e($product['name_ar']) ?></nav><div class="row g-4 mt-2"><div class="col-md-6"><img class="img-fluid rounded-4 border" src="<?= e($product['image_url'] ?: 'https://placehold.co/800x800?text=Product') ?>" alt="<?= e($product['name_ar']) ?>"></div><div class="col-md-6"><h1><?= e($product['name_ar']) ?></h1><p class="text-muted"><?= nl2br(e($product['description_ar'])) ?></p><h3 class="text-success"><?= e($productModel->displayPrice($product,$variants)) ?></h3><form method="post" action="<?= url('/cart/add') ?>" class="mt-4 card card-body"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><?php if($variants): ?><label class="form-label">اختر النوع</label><select name="variant_id" class="form-select"><?php foreach($variants as $v): ?><option value="<?= (int)$v['id'] ?>"><?= e($v['name_ar']) ?> — <?= money($v['price']) ?> (<?= (int)$v['stock'] ?> متاح)</option><?php endforeach; ?></select><?php elseif($product['is_weight_based']): ?><label class="form-label">الوزن</label><select name="weight_grams" class="form-select"><?php foreach(array_filter(array_map('intval', explode(',',$product['weight_options_grams']))) as $w): ?><option value="<?= $w ?>"><?= weight_label($w) ?> — <?= money(price_for_weight($product['price_per_kg'],$w)) ?></option><?php endforeach; ?></select><p class="small text-muted mt-2">السعر النهائي يُحتسب على الوزن الفعلي عند التحضير.</p><?php endif; ?><label class="form-label mt-3">الكمية</label><input type="number" min="1" name="quantity" value="1" class="form-control"><button class="btn btn-success btn-lg mt-3">إضافة إلى السلة</button></form></div></div></div>
